/**
 * Seed sensible per-game pricing tiers (GamePlan rows).
 *
 * For each tier we pick:
 *   - basePlanId   = the smallest active VPS Plan whose ramMB >= the tier's ramMB
 *                    (falls back to the largest plan if none is big enough).
 *   - osTemplateId = that game's OsTemplate (family=<game>, category=APPLICATION),
 *                    if one exists; otherwise null (deploy resolves it at runtime).
 *
 * Idempotent: dedupes by (gameFamily, name) and upserts.
 *
 * Run: cd /opt/nxeon && npx tsx prisma/seed-gameplans.ts
 */
import { PrismaClient } from "@prisma/client";

const db = new PrismaClient();

type TierSpec = {
  gameFamily: string;
  name: string;
  ramMB: number;
  cpuCores: number;
  diskGB: number;
  slots: number;
  priceCents: number;
  featured?: boolean;
};

// Retail prices in cents, monthly term. RAM/slots/price differ per game.
const TIERS: TierSpec[] = [
  // Minecraft — light, scales by player count.
  { gameFamily: "minecraft", name: "Minecraft — 2 GB / 10 slots", ramMB: 2048, cpuCores: 2, diskGB: 20, slots: 10, priceCents: 499 },
  { gameFamily: "minecraft", name: "Minecraft — 4 GB / 20 slots", ramMB: 4096, cpuCores: 2, diskGB: 30, slots: 20, priceCents: 899, featured: true },
  { gameFamily: "minecraft", name: "Minecraft — 8 GB / 50 slots", ramMB: 8192, cpuCores: 3, diskGB: 50, slots: 50, priceCents: 1599 },

  // Valheim — RAM-hungry world simulation.
  { gameFamily: "valheim", name: "Valheim — 4 GB / 10 players", ramMB: 4096, cpuCores: 2, diskGB: 30, slots: 10, priceCents: 999 },
  { gameFamily: "valheim", name: "Valheim — 8 GB / 20 players", ramMB: 8192, cpuCores: 3, diskGB: 50, slots: 20, priceCents: 1699, featured: true },

  // Rust — needs the most RAM & CPU, big populations.
  { gameFamily: "rust", name: "Rust — 4 GB / 40 slots", ramMB: 4096, cpuCores: 2, diskGB: 40, slots: 40, priceCents: 1299 },
  { gameFamily: "rust", name: "Rust — 6 GB / 60 slots", ramMB: 6144, cpuCores: 3, diskGB: 60, slots: 60, priceCents: 1799, featured: true },
  { gameFamily: "rust", name: "Rust — 10 GB / 150 slots", ramMB: 10240, cpuCores: 4, diskGB: 80, slots: 150, priceCents: 2999 },

  // Palworld — heavy, small-ish parties.
  { gameFamily: "palworld", name: "Palworld — 8 GB / 8 players", ramMB: 8192, cpuCores: 3, diskGB: 50, slots: 8, priceCents: 1499 },
  { gameFamily: "palworld", name: "Palworld — 16 GB / 32 players", ramMB: 16384, cpuCores: 4, diskGB: 80, slots: 32, priceCents: 2799, featured: true },

  // CS2 — competitive FPS, modest RAM.
  { gameFamily: "cs2", name: "CS2 — 2 GB / 12 slots", ramMB: 2048, cpuCores: 2, diskGB: 40, slots: 12, priceCents: 699 },
  { gameFamily: "cs2", name: "CS2 — 4 GB / 24 slots", ramMB: 4096, cpuCores: 3, diskGB: 50, slots: 24, priceCents: 1199, featured: true },

  // Terraria — lightweight sandbox.
  { gameFamily: "terraria", name: "Terraria — 2 GB / 8 players", ramMB: 2048, cpuCores: 1, diskGB: 20, slots: 8, priceCents: 449 },
  { gameFamily: "terraria", name: "Terraria — 4 GB / 16 players", ramMB: 4096, cpuCores: 2, diskGB: 30, slots: 16, priceCents: 799, featured: true },
];

async function main() {
  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { ramMB: "asc" } });
  if (plans.length === 0) {
    throw new Error("No active VPS plans found — run the main seed first (npx prisma db seed).");
  }
  const largest = plans[plans.length - 1];

  // Cache the first game image per family.
  const imageByFamily = new Map<string, string>();
  for (const spec of TIERS) {
    if (imageByFamily.has(spec.gameFamily)) continue;
    const os = await db.osTemplate.findFirst({
      where: { family: spec.gameFamily, category: "APPLICATION" },
      orderBy: { sortOrder: "asc" },
    });
    imageByFamily.set(spec.gameFamily, os?.id ?? "");
  }

  let created = 0;
  let updated = 0;
  let sortByGame = new Map<string, number>();

  for (const spec of TIERS) {
    const basePlan = plans.find((p) => p.ramMB >= spec.ramMB) ?? largest;
    const osId = imageByFamily.get(spec.gameFamily) || null;
    const sortOrder = (sortByGame.get(spec.gameFamily) ?? 0);
    sortByGame.set(spec.gameFamily, sortOrder + 1);

    const data = {
      gameFamily: spec.gameFamily,
      name: spec.name,
      ramMB: spec.ramMB,
      cpuCores: spec.cpuCores,
      diskGB: spec.diskGB,
      slots: spec.slots,
      priceCents: spec.priceCents,
      termMonths: 1,
      basePlanId: basePlan.id,
      osTemplateId: osId,
      featured: spec.featured ?? false,
      active: true,
      sortOrder,
    };

    // Dedupe by (gameFamily, name) — no DB unique constraint exists on the pair.
    const existing = await db.gamePlan.findFirst({
      where: { gameFamily: spec.gameFamily, name: spec.name },
    });
    if (existing) {
      await db.gamePlan.update({ where: { id: existing.id }, data });
      updated++;
    } else {
      await db.gamePlan.create({ data });
      created++;
    }
    console.log(
      `  ${spec.gameFamily.padEnd(10)} ${spec.name.padEnd(32)} → base=${basePlan.name} img=${osId ? "yes" : "auto"}`,
    );
  }

  const total = await db.gamePlan.count();
  console.log(`\nGamePlans seeded: ${created} created, ${updated} updated. Total in DB: ${total}.`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await db.$disconnect();
  });
