/**
 * Billing term definitions + discount math, shared by ordering, renewal,
 * the deploy wizard, invoices and the domain flow. Discounts are the platform's
 * promo (longer commitment = cheaper); tune here (or later via admin Settings).
 */

export type VpsTerm = { months: number; label: string; short: string; discountPct: number };

/** The ANNUAL term is 12 months — the one term whose discount is admin-configurable. */
export const ANNUAL_TERM_MONTHS = 12;

/**
 * The annual (12-month) commitment discount SHIPPED as the default, and the fallback
 * for the `annual_discount_percent` admin setting (lib/annual-discount.ts).
 *
 * It MUST equal the 12-month `VPS_TERMS` discountPct below: a platform whose
 * `Setting` table has no `annual_discount_percent` row must price the annual term
 * EXACTLY as it did before the setting existed, so no existing annual server's
 * renewal price moves the moment this wiring lands. The setting only ever raises or
 * lowers it deliberately, from the admin Billing panel.
 */
export const DEFAULT_ANNUAL_DISCOUNT_PCT = 20;

export const VPS_TERMS: VpsTerm[] = [
  { months: 1, label: "Monthly", short: "1 mo", discountPct: 0 },
  // Annual is admin-configurable — this is only the SHIPPED default. Every charge
  // path resolves the live rate via `annualDiscountPct()` and passes it through
  // `vpsTermPriceCents`; this constant is what an un-wired caller (and a 2-arg call)
  // falls back to. Keep it === DEFAULT_ANNUAL_DISCOUNT_PCT.
  { months: 12, label: "Annual", short: "1 yr", discountPct: DEFAULT_ANNUAL_DISCOUNT_PCT },
  // Biennial/Triennial are FIXED platform rates (NOT admin-configurable), so for these
  // terms the order and every renewal read the SAME constant here → displayed ===
  // charged === renewed by construction, with no per-account freezing needed. Editing a
  // rate here only reprices NEW orders; any existing longer-term account simply renews
  // at the new (always-cheaper) rate — never an overcharge.
  { months: 24, label: "Biennial", short: "2 yr", discountPct: 30 },
  { months: 36, label: "Triennial", short: "3 yr", discountPct: 40 },
];

export function vpsTerm(months: number): VpsTerm {
  return VPS_TERMS.find((t) => t.months === months) ?? VPS_TERMS[0];
}

/**
 * The discount percent to apply to a term.
 *
 * For the ANNUAL (12-month) term this is admin-configurable: pass the
 * `annualDiscountPct` resolved from the `annual_discount_percent` setting
 * (lib/annual-discount.ts) and it WINS over the shipped default. Every other term
 * keeps its fixed `VPS_TERMS` rate. Omitting the override — or passing a
 * non-finite value — falls back to the shipped default, so a 2-arg
 * `vpsTermPriceCents` call and any caller that has not been wired up price annual at
 * `DEFAULT_ANNUAL_DISCOUNT_PCT`, i.e. exactly what the platform shipped before.
 * Clamped to 0..90 here as a second line of defence behind the setting reader.
 */
export function termDiscountPct(months: number, annualDiscountPct?: number): number {
  if (months === ANNUAL_TERM_MONTHS && annualDiscountPct != null && Number.isFinite(annualDiscountPct)) {
    return Math.min(90, Math.max(0, annualDiscountPct));
  }
  return vpsTerm(months).discountPct;
}

/**
 * Total charge (cents) for a plan over a term, discount applied.
 *
 * `annualDiscountPct` (optional) overrides the ANNUAL term's discount with the
 * admin-configured rate; see `termDiscountPct`. It is the ONE knob that makes
 * annual billing configurable while keeping this the single price formula —
 * displayed (deploy wizard), charged (lib/order.ts) and renewed (renewalCharge)
 * all call this with the SAME resolved rate, so they cannot disagree.
 */
export function vpsTermPriceCents(monthlyCents: number, months: number, annualDiscountPct?: number): number {
  const pct = termDiscountPct(months, annualDiscountPct);
  return Math.round(monthlyCents * months * (1 - pct / 100));
}

/**
 * Generic term price — the product-agnostic name for the ONE term formula above.
 * Shared Hosting, Business Email, Game servers and NxCloud all price a term as
 * `monthlyCents × months × (1 − annualDiscount)` exactly the way a VPS does, so
 * they call THIS and there is a single arithmetic for every product+term. It is a
 * thin alias of `vpsTermPriceCents` on purpose: the annual discount is resolved
 * once (order) and re-resolved (renewal) against the SAME setting, so
 * displayed === charged === renewed holds for every product.
 */
export function termPriceCents(monthlyCents: number, months: number, annualDiscountPct?: number): number {
  return vpsTermPriceCents(monthlyCents, months, annualDiscountPct);
}

/**
 * The terms offered on the NON-VPS products (Shared Hosting, Business Email, Game
 * servers, NxCloud): the full ladder — Monthly, Annual (admin-configurable),
 * Biennial and Triennial — the SAME set VPS sells. Every product prices a term
 * through the one `termPriceCents` formula, so the longer-commitment discounts
 * (20 / 30 / 40%) apply uniformly across the platform.
 */
export const PRODUCT_TERMS: VpsTerm[] = [...VPS_TERMS];

/**
 * Clamp any term input from a product order form to a SUPPORTED product term —
 * one of the `PRODUCT_TERMS` months (1 / 12 / 24 / 36). A malformed / unlisted
 * value can therefore only ever fall back to the cheapest (monthly) term, never
 * grant a longer paid term the customer did not pay for. The order path then prices
 * whatever term this returns through `termPriceCents`, so the charge always matches
 * the term granted.
 */
export function normalizeProductTerm(months: unknown): number {
  const m = Math.round(Number(months));
  return PRODUCT_TERMS.some((t) => t.months === m) ? m : 1;
}

/**
 * Effective monthly-equivalent price after the term discount (for "$/mo" display).
 *
 * `months <= 0` returns the undiscounted monthly price rather than dividing by it.
 * This is not display hygiene — it is a money guard. `prorateDeltaCents`
 * (lib/proration.ts) prices BOTH halves of every upgrade and downgrade credit
 * through this function using `Server.termMonths`, and a 0 there made the division
 * `0 / 0` → NaN, which sails through `Math.round`, through `Math.max(0, delta)`
 * (NaN is not > 0, so the clamp returns NaN, not 0) and into `debitWallet` as the
 * amount to take. The result is a charge that either explodes at the database or,
 * on the credit side, writes NaN where a customer's balance used to be. The column
 * defaults to 1 and every writer clamps to >= 1 today, so this is a latch, not a
 * live bug — but a shared money function must not have a NaN in it.
 */
export function vpsEffectiveMonthly(monthlyCents: number, months: number, annualDiscountPct?: number): number {
  if (!Number.isFinite(months) || months <= 0) return Math.round(monthlyCents);
  return Math.round(vpsTermPriceCents(monthlyCents, months, annualDiscountPct) / months);
}

export type DomainTerm = { years: number; label: string; discountPct: number };

export const DOMAIN_TERMS: DomainTerm[] = [
  { years: 1, label: "1 year", discountPct: 0 },
  { years: 2, label: "2 years", discountPct: 5 },
  { years: 3, label: "3 years", discountPct: 10 },
];

export function domainTerm(years: number): DomainTerm {
  return DOMAIN_TERMS.find((t) => t.years === years) ?? DOMAIN_TERMS[0];
}

/** Total charge (cents) for a domain over N years, discount applied. */
export function domainTermPriceCents(perYearCents: number, years: number): number {
  const t = domainTerm(years);
  return Math.round(perYearCents * years * (1 - t.discountPct / 100));
}

/** Add whole months to a date (UTC-safe enough for billing windows). */
export function addMonths(from: Date, months: number): Date {
  const d = new Date(from);
  d.setMonth(d.getMonth() + months);
  return d;
}
